<?php
/* Wolf pre-flight check. Upload, open in the browser, fix any red items, then DELETE this file. */
error_reporting(0);
function row($ok, $name, $detail, $fix) { global $fails; if (!$ok) $fails++; echo '<div class="r ' . ($ok ? 'ok' : 'bad') . '"><b>' . ($ok ? '&#10003;' : '&#10007;') . ' ' . htmlspecialchars($name) . '</b><span>' . htmlspecialchars($detail) . '</span>' . ($ok ? '' : '<em>Fix: ' . htmlspecialchars($fix) . '</em>') . '</div>'; }
function tobytes($v) { $v = trim($v); $n = (int)$v; $l = strtolower(substr($v, -1)); if ($l == 'g') $n *= 1073741824; elseif ($l == 'm') $n *= 1048576; elseif ($l == 'k') $n *= 1024; return $n; }
function probe($url) { if (!function_exists('curl_init')) return 0; $c = curl_init($url); curl_setopt($c, CURLOPT_NOBODY, true); curl_setopt($c, CURLOPT_RETURNTRANSFER, true); curl_setopt($c, CURLOPT_TIMEOUT, 8); curl_exec($c); $code = (int)curl_getinfo($c, CURLINFO_HTTP_CODE); curl_close($c); return $code; }
$fails = 0;
header('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-store');
echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Wolf pre-flight check</title><style>body{font-family:system-ui,Segoe UI,Roboto,sans-serif;background:#0b1430;color:#f2f5ff;margin:0;padding:20px;line-height:1.45}main{max-width:680px;margin:0 auto}h1{font-size:24px;margin:0 0 4px}p{color:#9fb0d8}.r{background:#17254a;border:1px solid #25356a;border-radius:12px;padding:10px 12px;margin:8px 0}.r b{display:block}.r span{color:#9fb0d8;font-size:13px;display:block}.r em{display:block;color:#ffd9a0;font-size:13.5px;margin-top:4px;font-style:normal}.ok b{color:#14e0c0}.bad{border-color:#e5384b}.bad b{color:#ff8f9b}.sum{padding:14px;border-radius:14px;font-weight:800;margin:14px 0}.g{background:#14e0c022;border:1px solid #14e0c0}.rd{background:#e5384b22;border:1px solid #e5384b}</style></head><body><main><h1>Wolf pre-flight check</h1><p>Every line should be green. If one is red, do the fix, then refresh this page.</p>';
row(version_compare(PHP_VERSION, '8.1.0', '>='), 'PHP version', PHP_VERSION, 'In hPanel open Advanced, then PHP Configuration, and choose PHP 8.2 or newer.');
foreach (array('pdo_sqlite', 'curl', 'openssl', 'fileinfo', 'mbstring', 'json') as $e) row(extension_loaded($e), 'Extension: ' . $e, extension_loaded($e) ? 'loaded' : 'missing', 'In hPanel open Advanced, then PHP Configuration, then Extensions, and tick ' . $e . '.');
$sv = ''; $json = false;
if (extension_loaded('pdo_sqlite')) { try { $p = new PDO('sqlite::memory:'); $sv = (string)$p->query('select sqlite_version()')->fetchColumn(); $json = ((string)$p->query("select json_extract('{\"a\":1}','$.a')")->fetchColumn() === '1'); } catch (Exception $x) {} }
row($sv !== '' && version_compare($sv, '3.27.0', '>='), 'SQLite version', $sv !== '' ? $sv : 'not available', 'Ask Hostinger support for SQLite 3.27 or newer, or move to a plan that has it.');
row($json, 'SQLite JSON support', $json ? 'works' : 'missing', 'Ask Hostinger support to enable SQLite JSON functions.');
$t = __DIR__ . '/wolf_check_' . mt_rand(1000, 9999) . '.tmp'; $w = @file_put_contents($t, 'x') !== false; if ($w) { @unlink($t); }
row($w, 'Folder is writable', $w ? 'yes' : 'no', 'In File Manager, right-click the folder, choose Permissions, and set it to 755.');
row(!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off' || (isset($_SERVER['HTTP_X_FORWARDED_PROTO']) && $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https'), 'HTTPS (secure address)', 'needed for the microphone and install-to-home-screen', 'In hPanel open Security, then SSL, and switch SSL on for this subdomain. Then open this page with https://');
$um = tobytes(ini_get('upload_max_filesize')); $pm = tobytes(ini_get('post_max_size'));
row($um >= 8388608 && $pm >= 8388608, 'Photo upload limits', 'upload ' . ini_get('upload_max_filesize') . ', post ' . ini_get('post_max_size'), 'In hPanel PHP Configuration, set upload_max_filesize and post_max_size to at least 8M.');
$g = probe('https://generativelanguage.googleapis.com/'); row($g > 0, 'Can reach Google AI', $g ? 'reply ' . $g : 'no reply', 'Outgoing connections may be blocked. Ask Hostinger support to allow outgoing HTTPS.');
$c = probe('https://calendar.google.com/'); row($c > 0, 'Can reach Google Calendar', $c ? 'reply ' . $c : 'no reply', 'Outgoing connections may be blocked. Ask Hostinger support to allow outgoing HTTPS.');
$df = @disk_free_space(__DIR__); row($df === false || $df > 500 * 1048576, 'Disk space free', $df === false ? 'unknown' : round($df / 1048576) . ' MB', 'Free up space in File Manager.');
row(is_file(__DIR__ . '/api.php') && is_file(__DIR__ . '/index.html') && is_file(__DIR__ . '/app.js'), 'Wolf files uploaded', 'api.php, index.html, app.js', 'Upload and extract wolf_upload.zip into this same folder.');
echo '<div class="sum ' . ($fails ? 'rd' : 'g') . '">' . ($fails ? $fails . ' thing(s) to fix before you carry on.' : 'All green. Now delete check.php, then open the Wolf address on your phone.') . '</div><p>Server time: ' . date('Y-m-d H:i:s T') . '. This page shows nothing private.</p></main></body></html>';
